import hashlib,json,os,subprocess,sys
from pathlib import Path

ROOT=Path('/home/kestrel/projects/luma-editor');os.chdir(ROOT)
BASE=Path('/tmp/canoli-wet-gesture-performance-baseline')
P='/tmp/canoli-wet-performance-head-'
path=lambda name:Path(P+name)
sha=lambda name:hashlib.sha256(Path(name).read_bytes()).hexdigest()

def inputs():
    names=set(json.loads((BASE/'source-manifest.json').read_text()))
    for directory in ['src','assembly','server','tests','scripts']:
        names.update(str(p) for p in Path(directory).rglob('*') if p.is_file() and '__pycache__' not in p.parts and p.suffix!='.pyc')
    return {name:sha(name) for name in sorted(names)}

def verify():
    expected=json.loads(path('corrected-sources.json' if sys.argv[1]=='verify-corrected' else 'frozen.json').read_text())
    if sys.argv[1]=='verify-corrected':
        original=json.loads(path('frozen.json').read_text());assert set(expected)==set(original) and [name for name in original if original[name]!=expected[name]]==['tests/canvas-cursors.e2e.ts']
    assert inputs()==expected,'Source inventory changed'
    counts={}
    for kind,file in [('release',path('release-final.json')),('generated',path('generated-final.json')),('prior',BASE/'prior-evidence.json')]:
        values=json.loads(file.read_text());changed=[name for name,digest in values.items() if not Path(name).is_file() or sha(name)!=digest]
        assert not changed,(kind,changed);counts[kind]=len(values)
    assert sha('public/wasm/pixels.wasm')==sha('dist/wasm/pixels.wasm')
    return counts

def cases(suites,parents=()):
    for suite in suites:
        titles=parents+(suite.get('title',''),)
        for spec in suite.get('specs',[]):
            for test in spec.get('tests',[]):
                yield (spec['file'],titles+(spec['title'],),test.get('projectName','')),test
        yield from cases(suite.get('suites',[]),titles)

def capture(kind):
    report=json.loads(path(kind+'-final.json').read_text())
    catalog=json.loads(path(kind+'-catalog.json').read_text())
    actual=list(cases(report['suites']));planned=list(cases(catalog['suites']))
    keys=[key for key,test in actual];expected=[key for key,test in planned]
    assert len(set(keys))==len(keys) and sorted(keys)==sorted(expected),'Catalog mismatch'
    result={'report':report,'catalog':catalog,'caseKeys':keys,'verification':verify()}
    path(kind+'-captured.json').write_text(json.dumps(result,indent=2)+'\n')
    return report['stats'],len(keys)

kind=sys.argv[1]
if kind=='freeze':
    assert not path('frozen.json').exists(),'Frozen run already exists'
    path('frozen.json').write_text(json.dumps(inputs(),indent=2)+'\n')
    path('release-final.json').write_text(json.dumps({str(p):sha(p) for p in sorted(Path('dist').rglob('*')) if p.is_file()},indent=2)+'\n')
    path('generated-final.json').write_text(json.dumps({'public/wasm/pixels.wasm':sha('public/wasm/pixels.wasm')},indent=2)+'\n')
    print('Frozen',len(inputs()),verify())
elif kind in ['verify','verify-corrected']:print(verify())
elif kind in ['native','production']:
    verify();config='/tmp/canoli-wet-performance-head-'+('accept.config.ts' if kind=='native' else 'production.config.ts')
    env={**os.environ,'PLAYWRIGHT_CHROMIUM_EXECUTABLE':'/home/kestrel/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome','CANOLI_PSB_PYTHON':'/tmp/canoli-psb-check/bin/python','CANOLI_PDF_PYTHON':'/tmp/canoli-pdf-check/bin/python','PSD_READER_PYTHONPATH':'/tmp/canoli-psb-check/lib/python3.10/site-packages'}
    command=['npx','playwright','test','--config',config]
    path(kind+'-command.json').write_text(json.dumps(command)+'\n')
    with path(kind+'-catalog.json').open('x') as output:subprocess.run(command+['--list','--reporter=json'],env=env,stdout=output,check=True)
    verify()
    with path(kind+'-final.log').open('x') as output:result=subprocess.run(command,env=env,stdout=output,stderr=subprocess.STDOUT)
    path(kind+'-exit.json').write_text(json.dumps({'exitCode':result.returncode})+'\n')
    print(kind,capture(kind));sys.exit(result.returncode)
else:raise ValueError(kind)

